import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-npm-start-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'persistent.sqlite') }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const url = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Start timed out')), 10000);
    child.stdout.on('data', (chunk) => {
      const match = String(chunk).match(/http:\\/\\/0\\.0\\.0\\.0:(\\d+)/);
      if (match) { clearTimeout(timeout); resolve('http://127.0.0.1:' + match[1]); }
    });
    child.once('exit', (code) => { clearTimeout(timeout); reject(new Error('Exited: ' + code)); });
  });
  const response = await fetch(url + '/health');
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  assert.equal((await fetch(url + '/completion.js')).status, 200);
  console.log('npm start: 0.0.0.0 binding, PORT, DB_PATH, /health and completion script verified');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await new Promise((resolve) => child.once('exit', resolve));
  await rm(directory, { recursive: true, force: true });
}
NODE"

